// Code node: "Build Extraction Prompt"
// Runs once per Gmail message (Gmail node, Simplify OFF -> raw Gmail API
// message resource). Decodes the plain-text body and builds the prompt for
// the first extraction attempt against the Anthropic Messages API.
//
// Deliberately: the prompt below carries ONLY the decoded body text and
// subject, never the Gmail "From" header or any sender metadata. That's a
// structural choice, not just an instruction to the model - the model has
// no way to use the From header for identity because it is never given to
// it. Identity must come from the body/signature alone, which matches how
// the seed data (data/synthetic/part2_seed.md) was built: every email is
// actually sent from the same Gmail account.

function decodeBase64Url(data) {
  if (!data) return "";
  const normalized = data.replace(/-/g, "+").replace(/_/g, "/");
  return Buffer.from(normalized, "base64").toString("utf8");
}

function stripHtml(html) {
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .trim();
}

function findPart(payload, mimeType) {
  if (!payload) return null;
  if (payload.mimeType === mimeType && payload.body && payload.body.data) {
    return payload.body.data;
  }
  if (Array.isArray(payload.parts)) {
    for (const part of payload.parts) {
      const found = findPart(part, mimeType);
      if (found) return found;
    }
  }
  return null;
}

function getBodyText(payload) {
  const plain = findPart(payload, "text/plain");
  if (plain) return decodeBase64Url(plain).trim();

  const html = findPart(payload, "text/html");
  if (html) return stripHtml(decodeBase64Url(html));

  if (payload && payload.body && payload.body.data) {
    return decodeBase64Url(payload.body.data).trim();
  }
  return "";
}

function getHeader(payload, name) {
  const headers = (payload && payload.headers) || [];
  const header = headers.find(
    (h) => h.name && h.name.toLowerCase() === name.toLowerCase()
  );
  return header ? header.value : "";
}

function buildPrompt(subject, bodyText) {
  return [
    "You are extracting attendee contact details from a single conference",
    "RSVP email for the Atlas AI Summit.",
    "",
    "Read ONLY the subject and body text below. Do not assume anything",
    "about who sent this email - there is no reliable sender identity",
    "available to you, so the attendee's name, organisation, email, and",
    "phone must come only from what is written in the body/signature.",
    "",
    `Subject: ${subject}`,
    "Body:",
    "---",
    bodyText,
    "---",
    "",
    "Respond with ONLY a JSON object, no other text, no markdown code",
    "fences, in exactly this shape:",
    '{"name": string or null, "organisation": string or null, ' +
      '"email": string or null, "phone": string or null}',
    "",
    "Use null for any field not stated in the body. Do not invent values.",
  ].join("\n");
}

return items.map((item, index) => {
  const message = item.json;
  const bodyText = getBodyText(message.payload);
  const subject = getHeader(message.payload, "Subject");

  return {
    json: {
      __kind: "email",
      emailIndex: index + 1,
      messageId: message.id || null,
      subject,
      bodyText,
      attempt: 1,
      prompt: buildPrompt(subject, bodyText),
    },
  };
});

// Code node: "Validate & Shape (Attempt 1)"
// Input: the Anthropic Messages API response for the FIRST extraction call.
// Pulls sibling fields (subject, bodyText, emailIndex, attempt) back from
// the "Build Extraction Prompt" node by name, since the HTTP Request node
// in between replaces $json with the raw API response. n8n preserves 1:1
// item pairing through HTTP Request, so $('Node Name').item is safe here.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function parseClaudeJson(text) {
  if (!text) return { ok: false, reason: "empty response text" };
  let cleaned = text.trim();
  // Strip ```json ... ``` or ``` ... ``` fences if the model added them.
  const fenceMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenceMatch) cleaned = fenceMatch[1].trim();
  try {
    return { ok: true, value: JSON.parse(cleaned) };
  } catch (err) {
    return { ok: false, reason: `invalid JSON: ${err.message}` };
  }
}

function validate(extracted) {
  if (!extracted || typeof extracted !== "object") {
    return { valid: false, reason: "extraction is not a JSON object" };
  }
  if (!extracted.name || typeof extracted.name !== "string" || !extracted.name.trim()) {
    return { valid: false, reason: "name is missing or empty" };
  }
  if (extracted.email && !EMAIL_RE.test(String(extracted.email).trim())) {
    return { valid: false, reason: `email "${extracted.email}" is not a valid email format` };
  }
  return { valid: true, reason: null };
}

const results = [];
for (let i = 0; i < items.length; i++) {
  const response = items[i].json;
  const prior = $("Build Extraction Prompt").all()[i].json;

  const textBlock =
    response.content && response.content[0] && response.content[0].text;
  const parsed = parseClaudeJson(textBlock);

  let valid = false;
  let reason = null;
  let extracted = null;

  if (!parsed.ok) {
    reason = parsed.reason;
  } else {
    extracted = parsed.value;
    const check = validate(extracted);
    valid = check.valid;
    reason = check.reason;
  }

  results.push({
    json: {
      __kind: "email",
      emailIndex: prior.emailIndex,
      messageId: prior.messageId,
      subject: prior.subject,
      bodyText: prior.bodyText,
      attempt: prior.attempt,
      valid,
      reason,
      name: extracted ? extracted.name || null : null,
      organisation: extracted ? extracted.organisation || null : null,
      email: extracted ? extracted.email || null : null,
      phone: extracted ? extracted.phone || null : null,
      extractionStatus: valid ? "extracted_first_try" : "needs_retry",
      sources: [`Email ${prior.emailIndex}`],
    },
  });
}

return results;

// Code node: "Build Retry Prompt"
// Input: items that failed validation after the first extraction attempt
// (the FALSE branch of the "Valid? (Attempt 1)" IF node). Builds a second
// prompt that shows the model its own invalid output and the validation
// error, and asks it to correct it. This is the visible self-correction
// step - its result is recorded by "Validate & Shape (Retry)" regardless
// of whether the retry succeeds.

function buildRetryPrompt(subject, bodyText, previousAttemptJson, reason) {
  return [
    "Your previous attempt to extract attendee contact details from this",
    "conference RSVP email was invalid. Fix it.",
    "",
    `Validation error: ${reason}`,
    "",
    `Your previous output was: ${previousAttemptJson}`,
    "",
    "Read ONLY the subject and body text below. Do not assume anything",
    "about who sent this email - the attendee's name, organisation, email,",
    "and phone must come only from what is written in the body/signature.",
    "",
    `Subject: ${subject}`,
    "Body:",
    "---",
    bodyText,
    "---",
    "",
    "Respond with ONLY a JSON object, no other text, no markdown code",
    "fences, in exactly this shape:",
    '{"name": string or null, "organisation": string or null, ' +
      '"email": string or null, "phone": string or null}',
    "",
    "Use null for any field not stated in the body. Do not invent values.",
  ].join("\n");
}

return items.map((item) => {
  const prior = item.json;
  const previousAttemptJson = JSON.stringify({
    name: prior.name,
    organisation: prior.organisation,
    email: prior.email,
    phone: prior.phone,
  });

  return {
    json: {
      __kind: "email",
      emailIndex: prior.emailIndex,
      messageId: prior.messageId,
      subject: prior.subject,
      bodyText: prior.bodyText,
      attempt: 2,
      prompt: buildRetryPrompt(prior.subject, prior.bodyText, previousAttemptJson, prior.reason),
    },
  };
});

// Code node: "Validate & Shape (Retry)"
// Same logic as "Validate & Shape (Attempt 1)", but pulls sibling fields
// from "Build Retry Prompt" instead, since this validates the SECOND
// (retry) extraction call's response.

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function parseClaudeJson(text) {
  if (!text) return { ok: false, reason: "empty response text" };
  let cleaned = text.trim();
  const fenceMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/i);
  if (fenceMatch) cleaned = fenceMatch[1].trim();
  try {
    return { ok: true, value: JSON.parse(cleaned) };
  } catch (err) {
    return { ok: false, reason: `invalid JSON: ${err.message}` };
  }
}

function validate(extracted) {
  if (!extracted || typeof extracted !== "object") {
    return { valid: false, reason: "extraction is not a JSON object" };
  }
  if (!extracted.name || typeof extracted.name !== "string" || !extracted.name.trim()) {
    return { valid: false, reason: "name is missing or empty" };
  }
  if (extracted.email && !EMAIL_RE.test(String(extracted.email).trim())) {
    return { valid: false, reason: `email "${extracted.email}" is not a valid email format` };
  }
  return { valid: true, reason: null };
}

const results = [];
for (let i = 0; i < items.length; i++) {
  const response = items[i].json;
  const prior = $("Build Retry Prompt").all()[i].json;

  const textBlock =
    response.content && response.content[0] && response.content[0].text;
  const parsed = parseClaudeJson(textBlock);

  let valid = false;
  let reason = null;
  let extracted = null;

  if (!parsed.ok) {
    reason = parsed.reason;
  } else {
    extracted = parsed.value;
    const check = validate(extracted);
    valid = check.valid;
    reason = check.reason;
  }

  results.push({
    json: {
      __kind: "email",
      emailIndex: prior.emailIndex,
      messageId: prior.messageId,
      subject: prior.subject,
      bodyText: prior.bodyText,
      attempt: prior.attempt,
      valid,
      reason,
      name: extracted ? extracted.name || null : null,
      organisation: extracted ? extracted.organisation || null : null,
      email: extracted ? extracted.email || null : null,
      phone: extracted ? extracted.phone || null : null,
      extractionStatus: valid ? "extracted_after_retry" : "extraction_failed",
      sources: [`Email ${prior.emailIndex}`],
    },
  });
}

return results;

// Code node: "Mark Extraction Failed"
// Input: items still invalid after the retry (FALSE branch of "Valid?
// (Retry)"). Whatever partial fields the model produced are unreliable, so
// this clears them and shapes the item into the same candidate-row shape
// used everywhere downstream, flagged for a human to resolve.

return items.map((item) => {
  const prior = item.json;
  return {
    json: {
      __kind: "email",
      emailIndex: prior.emailIndex,
      messageId: prior.messageId,
      subject: prior.subject,
      name: null,
      organisation: null,
      email: null,
      phone: null,
      extractionStatus: "extraction_failed",
      attempts: 2,
      sources: [`Email ${prior.emailIndex}`],
      flags: [`extraction_failed: ${prior.reason}`],
    },
  };
});

// Code node: "Parse Calendar"
// Deterministic parsing (no LLM) of Google Calendar event descriptions.
// Expects events whose description contains lines shaped like
// "- Name, Organisation" (see data/synthetic/part2_seed.md). Only keeps
// events whose title actually contains "Atlas AI Summit" - the Calendar
// node's own query narrows this already, but this is the one place that
// deterministically enforces it regardless of how loose that query match
// is.

const ATTENDEE_LINE_RE = /^[-*]\s*(.+?),\s*(.+)$/;

const results = [];

items.forEach((item, eventIndex) => {
  const event = item.json;
  const title = event.summary || event.title || "";
  if (!title.includes("Atlas AI Summit")) return;

  const description = event.description || "";
  const lines = description.split(/\r?\n/);

  lines.forEach((line) => {
    const trimmed = line.trim();
    const match = trimmed.match(ATTENDEE_LINE_RE);
    if (!match) return;

    const name = match[1].trim();
    const organisation = match[2].trim();

    results.push({
      json: {
        __kind: "calendar",
        name,
        organisation,
        email: null,
        phone: null,
        extractionStatus: "calendar_parsed",
        attempts: 1,
        sources: [`Event: ${title}`],
        flags: [],
      },
    });
  });
});

return results;

// Code node: "Normalise"
// Input: merged email-extraction candidates + calendar-parsed candidates.
// Adds normalised fields used for matching further down the pipeline.
// Display fields (name/organisation/email/phone) are left as extracted;
// only the normalised* fields are lowercased/reformatted.

function collapseWhitespace(s) {
  return s ? String(s).trim().replace(/\s+/g, " ") : null;
}

function normaliseEmail(email) {
  return email ? String(email).trim().toLowerCase() : null;
}

function normalisePhone(raw) {
  if (!raw) return null;
  let digits = String(raw).replace(/[^\d+]/g, "");
  if (digits.startsWith("+27")) {
    return "+27" + digits.slice(3).replace(/\D/g, "");
  }
  if (digits.startsWith("27") && digits.length >= 11) {
    return "+" + digits;
  }
  if (digits.startsWith("0")) {
    return "+27" + digits.slice(1);
  }
  if (digits.startsWith("+")) {
    return digits;
  }
  if (digits.length > 0) {
    return "+27" + digits;
  }
  return null;
}

function squash(s) {
  return s ? String(s).toLowerCase().replace(/[^a-z0-9]/g, "") : null;
}

return items.map((item) => {
  const c = item.json;
  const name = collapseWhitespace(c.name);
  const organisation = collapseWhitespace(c.organisation);

  return {
    json: {
      ...c,
      name,
      organisation,
      email: c.email ? String(c.email).trim() : null,
      phone: c.phone ? String(c.phone).trim() : null,
      normalisedName: name ? name.toLowerCase() : null,
      normalisedOrg: organisation ? organisation.toLowerCase() : null,
      squashedOrg: squash(organisation),
      normalisedEmail: normaliseEmail(c.email),
      normalisedPhone: normalisePhone(c.phone),
    },
  };
});

// Code node: "Tag Directory"
// Input: speakers.json fetched by the HTTP Request node. n8n's HTTP
// Request node splits a top-level JSON array response into one item per
// array element automatically, so each item here is already one speaker
// record. This just tags them and adds the same normalised fields used
// for matching elsewhere, so "Verify & Dedupe" can compare like with like.

function collapseWhitespace(s) {
  return s ? String(s).trim().replace(/\s+/g, " ") : null;
}

function normalisePhone(raw) {
  if (!raw) return null;
  let digits = String(raw).replace(/[^\d+]/g, "");
  if (digits.startsWith("+27")) {
    return "+27" + digits.slice(3).replace(/\D/g, "");
  }
  if (digits.startsWith("27") && digits.length >= 11) {
    return "+" + digits;
  }
  if (digits.startsWith("0")) {
    return "+27" + digits.slice(1);
  }
  if (digits.startsWith("+")) {
    return digits;
  }
  if (digits.length > 0) {
    return "+27" + digits;
  }
  return null;
}

function squash(s) {
  return s ? String(s).toLowerCase().replace(/[^a-z0-9]/g, "") : null;
}

return items.map((item) => {
  const speaker = item.json;
  const name = collapseWhitespace(speaker.full_name);
  const organisation = collapseWhitespace(speaker.organisation);

  return {
    json: {
      __kind: "directory",
      speaker_id: speaker.speaker_id,
      name,
      organisation,
      email: speaker.email || null,
      phone: speaker.phone || null,
      normalisedName: name ? name.toLowerCase() : null,
      normalisedOrg: organisation ? organisation.toLowerCase() : null,
      squashedOrg: squash(organisation),
      normalisedEmail: speaker.email ? String(speaker.email).trim().toLowerCase() : null,
      normalisedPhone: normalisePhone(speaker.phone),
    },
  };
});

// Code node: "Verify & Dedupe"
// Input: normalised candidate rows (__kind 'email'/'calendar') merged with
// the tagged speaker directory (__kind 'directory'). Resolves each
// candidate against the directory, then dedupes resolved candidates into
// one row per real attendee. Outputs __kind 'attendee' rows.

const NAME_MATCH_THRESHOLD = 2; // max Levenshtein edits to call two names "the same"
const ORG_MATCH_THRESHOLD = 2; // max Levenshtein edits on squashed org strings

function levenshtein(a, b) {
  if (a === b) return 0;
  if (!a) return b ? b.length : 0;
  if (!b) return a.length;
  const m = a.length;
  const n = b.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,
        dp[i][j - 1] + 1,
        dp[i - 1][j - 1] + cost
      );
    }
  }
  return dp[m][n];
}

const all = items.map((i) => i.json);
const directory = all.filter((i) => i.__kind === "directory");
const candidates = all.filter((i) => i.__kind === "email" || i.__kind === "calendar");

function findExact(candidate) {
  if (candidate.normalisedEmail) {
    const hit = directory.find((d) => d.normalisedEmail === candidate.normalisedEmail);
    if (hit) return { speaker: hit, via: "exact_email" };
  }
  if (candidate.normalisedPhone) {
    const hit = directory.find((d) => d.normalisedPhone === candidate.normalisedPhone);
    if (hit) return { speaker: hit, via: "exact_phone" };
  }
  return null;
}

function bestNameMatch(candidate) {
  if (!candidate.normalisedName) return null;
  let best = null;
  let bestDist = Infinity;
  for (const speaker of directory) {
    const dist = levenshtein(candidate.normalisedName, speaker.normalisedName || "");
    if (dist < bestDist) {
      bestDist = dist;
      best = speaker;
    }
  }
  if (best && bestDist <= NAME_MATCH_THRESHOLD) return { speaker: best, distance: bestDist };
  return null;
}

function orgMatchSet(candidate) {
  if (!candidate.squashedOrg) return [];
  let bestDist = Infinity;
  for (const speaker of directory) {
    const dist = levenshtein(candidate.squashedOrg, speaker.squashedOrg || "");
    if (dist < bestDist) bestDist = dist;
  }
  if (bestDist > ORG_MATCH_THRESHOLD) return [];
  return directory.filter(
    (speaker) => levenshtein(candidate.squashedOrg, speaker.squashedOrg || "") === bestDist
  );
}

function resolveOne(candidate) {
  const changes = [];
  const flags = Array.isArray(candidate.flags) ? [...candidate.flags] : [];

  if (candidate.extractionStatus === "extraction_failed") {
    return {
      ...candidate,
      status: "extraction_failed",
      speaker_id: null,
      candidates: [],
      changes,
      flags,
    };
  }

  const exact = findExact(candidate);
  const nameMatch = bestNameMatch(candidate);
  const orgSet = orgMatchSet(candidate);
  const orgIds = orgSet.map((s) => s.speaker_id);

  let speaker = null;
  let status = null;
  let ambiguousCandidates = [];

  if (exact) {
    speaker = exact.speaker;
    status = "confirmed";
  } else if (nameMatch && orgIds.length > 0 && !orgIds.includes(nameMatch.speaker.speaker_id)) {
    // Best name match and best org match disagree on WHO this is.
    status = "flagged_ambiguous";
    ambiguousCandidates = Array.from(new Set([nameMatch.speaker.speaker_id, ...orgIds]));
    flags.push(
      `name best-matches ${nameMatch.speaker.speaker_id} (${nameMatch.speaker.name}) but ` +
        `organisation best-matches ${orgIds.join("/")} - not auto-resolved`
    );
  } else if (nameMatch) {
    speaker = nameMatch.speaker;
    status = nameMatch.distance === 0 ? "confirmed" : "corrected";
  } else if (!candidate.normalisedName && orgIds.length === 1) {
    speaker = orgSet[0];
    status = "corrected";
  }

  if (status === "flagged_ambiguous") {
    return {
      ...candidate,
      status,
      speaker_id: null,
      candidates: ambiguousCandidates,
      changes,
      flags,
    };
  }

  if (!speaker) {
    return {
      ...candidate,
      status: "new_delegate",
      speaker_id: null,
      candidates: [],
      changes,
      flags,
    };
  }

  // Identity resolved to `speaker` - reconcile field-level differences.
  let resultName = candidate.name;
  if (candidate.name && speaker.name && candidate.name !== speaker.name) {
    changes.push(`full_name: '${candidate.name}' -> '${speaker.name}'`);
    resultName = speaker.name;
    status = "corrected";
  } else if (!candidate.name) {
    resultName = speaker.name;
  }

  let resultOrg = candidate.organisation;
  if (candidate.organisation && speaker.organisation && candidate.organisation !== speaker.organisation) {
    changes.push(`organisation: '${candidate.organisation}' -> '${speaker.organisation}'`);
    resultOrg = speaker.organisation;
    status = "corrected";
  } else if (!candidate.organisation) {
    resultOrg = speaker.organisation;
  }

  let resultEmail = candidate.email;
  if (!candidate.email && speaker.email) {
    changes.push(`email: filled from directory ('${speaker.email}')`);
    resultEmail = speaker.email;
    status = "corrected";
  } else if (candidate.email && speaker.email && candidate.normalisedEmail !== speaker.normalisedEmail) {
    flags.push(`RSVP email '${candidate.email}' differs from directory email '${speaker.email}'`);
    status = "flagged_email_mismatch";
  }

  let resultPhone = candidate.phone;
  if (!candidate.phone && speaker.phone) {
    resultPhone = speaker.phone;
  }

  return {
    ...candidate,
    name: resultName,
    organisation: resultOrg,
    email: resultEmail,
    phone: resultPhone,
    status,
    speaker_id: speaker.speaker_id,
    candidates: [],
    changes,
    flags,
  };
}

const resolved = candidates.map(resolveOne);

// Dedupe: group by speaker_id, else by ambiguous-candidate-set, else by
// normalised email/phone, else treat as a distinct new delegate.
const groups = new Map();

function groupKey(row) {
  if (row.speaker_id) return `speaker:${row.speaker_id}`;
  if (row.status === "flagged_ambiguous") return `ambiguous:${[...row.candidates].sort().join("+")}`;
  if (row.normalisedEmail) return `email:${row.normalisedEmail}`;
  if (row.normalisedPhone) return `phone:${row.normalisedPhone}`;
  return `new:${row.normalisedName || Math.random()}`;
}

for (const row of resolved) {
  const key = groupKey(row);
  if (!groups.has(key)) {
    groups.set(key, { ...row, sources: [...(row.sources || [])] });
    continue;
  }
  const existing = groups.get(key);
  existing.sources = Array.from(new Set([...(existing.sources || []), ...(row.sources || [])]));
  existing.changes = Array.from(new Set([...(existing.changes || []), ...(row.changes || [])]));
  existing.flags = Array.from(new Set([...(existing.flags || []), ...(row.flags || [])]));
  // Prefer a non-null value already on the group; otherwise take this row's.
  existing.name = existing.name || row.name;
  existing.organisation = existing.organisation || row.organisation;
  existing.email = existing.email || row.email;
  existing.phone = existing.phone || row.phone;
  // "corrected"/"flagged_*" outrank a plain "confirmed" when merging.
  if (existing.status === "confirmed" && row.status !== "confirmed") {
    existing.status = row.status;
  }
}

return Array.from(groups.values()).map((row) => ({
  json: {
    __kind: "attendee",
    name: row.name,
    organisation: row.organisation,
    email: row.email,
    phone: row.phone,
    speaker_id: row.speaker_id || null,
    status: row.status,
    candidates: row.candidates || [],
    sources: row.sources || [],
    changes: row.changes || [],
    flags: row.flags || [],
  },
}));

// Code node: "Tag Answer Key"
// Input: the single JSON object fetched from part2_answer_key.json. Just
// tags it so it survives the merge into the "Score vs Answer Key" node
// alongside the attendee rows.

return items.map((item) => ({
  json: {
    __kind: "answer_key",
    answerKey: item.json,
  },
}));

// Code node: "Score vs Answer Key"
// Input: resolved attendee rows (__kind 'attendee') merged with the tagged
// answer key (__kind 'answer_key'). Passes the attendee rows through
// unchanged and adds one extra item (__kind 'score_summary') reporting
// "Planted errors caught: X / 8" plus a per-error pass/fail breakdown.
//
// Each check below is keyed to one planted_errors[].id from
// data/synthetic/part2_answer_key.json and inspects the final attendee
// list for the specific, documented resolution that error is supposed to
// produce - it does not require exact string equality with every field in
// the answer key, since several reasonable (but not byte-identical)
// resolutions can be equally "correct" for a flagged/ambiguous case.

const all = items.map((i) => i.json);
const attendees = all.filter((i) => i.__kind === "attendee");
const answerKeyItem = all.find((i) => i.__kind === "answer_key");
const answerKey = answerKeyItem ? answerKeyItem.answerKey : null;

function bySpeaker(id) {
  return attendees.find((a) => a.speaker_id === id);
}

function hasChange(attendee, substrings) {
  if (!attendee || !Array.isArray(attendee.changes)) return false;
  return attendee.changes.some((c) => substrings.every((s) => c.includes(s)));
}

const checks = [
  {
    id: "err-1-phone-format",
    pass: () => {
      const a = bySpeaker("SP-013");
      return !!a && a.status !== "new_delegate" && a.status !== "flagged_ambiguous";
    },
  },
  {
    id: "err-2-misspelled-org",
    pass: () => {
      const a = bySpeaker("SP-016");
      return !!a && a.organisation === "Silverline Robotics" && hasChange(a, ["organisation"]);
    },
  },
  {
    id: "err-3-missing-email",
    pass: () => {
      const a = bySpeaker("SP-019");
      return !!a && a.email === "joseph.torres@example.org";
    },
  },
  {
    id: "err-4-duplicate-rsvp",
    pass: () => {
      const a = bySpeaker("SP-008");
      return !!a && a.name === "Paige Williams" && (a.sources || []).length >= 2;
    },
  },
  {
    id: "err-5-identity-collision",
    pass: () => {
      const flagged = attendees.find(
        (a) =>
          a.status === "flagged_ambiguous" &&
          Array.isArray(a.candidates) &&
          a.candidates.includes("SP-001") &&
          a.candidates.includes("SP-002")
      );
      return !!flagged;
    },
  },
  {
    id: "err-6-email-mismatch",
    pass: () => {
      const a = bySpeaker("SP-011");
      return !!a && a.status === "flagged_email_mismatch";
    },
  },
  {
    id: "err-7-not-in-directory",
    pass: () => {
      return attendees.some(
        (a) => a.status === "new_delegate" && a.name && a.name.includes("Priya Naidoo")
      );
    },
  },
  {
    id: "err-8-calendar-org-typo",
    pass: () => {
      const a = bySpeaker("SP-019");
      return !!a && a.organisation === "Horizon Cognition" && hasChange(a, ["Horizon Cognition"]);
    },
  },
];

const results = checks.map((check) => ({
  id: check.id,
  passed: check.pass(),
}));

const passedCount = results.filter((r) => r.passed).length;

const output = attendees.map((a) => ({ json: a }));
output.push({
  json: {
    __kind: "score_summary",
    summary: `Planted errors caught: ${passedCount} / ${checks.length}`,
    results,
    attendee_count: attendees.length,
    expected_attendee_count: answerKey ? answerKey.expected_final_attendee_count : null,
  },
});

return output;

// Code node: "Split Attendees for CSV"
// Input: the passthrough output of "Score vs Answer Key" (attendee rows
// plus one score_summary row). Keeps only the attendee rows, flattens the
// array fields to plain strings so "Convert to File" produces a readable
// CSV column instead of "[object Object]".

return items
  .filter((item) => item.json.__kind === "attendee")
  .map((item) => {
    const a = item.json;
    return {
      json: {
        name: a.name,
        organisation: a.organisation,
        email: a.email,
        phone: a.phone,
        speaker_id: a.speaker_id || "",
        status: a.status,
        candidates: (a.candidates || []).join("; "),
        sources: (a.sources || []).join("; "),
        changes: (a.changes || []).join("; "),
        flags: (a.flags || []).join("; "),
      },
    };
  });
